#include <cstddef>
#include <iostream>
struct ExampleStruct {
    char firstMember;  // Typically 1 byte
    int secondMember;  // Typically 4 bytes, with possible padding
};
// Overload operator& to demonstrate it doesn't affect offsetof
char& operator&(ExampleStruct& s) { return s.firstMember; }  // Invalid overload, but for illustration
int main() {
    std::cout << offsetof(ExampleStruct, firstMember) << std::endl;  // Expected: 0
    std::cout << offsetof(ExampleStruct, secondMember) << std::endl;  // Expected: value based on alignment, e.g., 4 if padded
    return 0;
}
